// === Wrong brand signal matching ===
// Mode: "Run Once for All Items". Input = rows from WB: Get signals.

const agg = $('Aggregate').first().json.data[0];
const content = agg.original_ticket_content || {};
const translated = agg.translated_data || {};
const translations = translated.translations || {};

const parts = [
  content.title,
  content.description,
  translations.title,
  translations.description
];

// Strip quoted history and signatures BEFORE matching. Replies carry our own
// footer and helpdesk subdomain, which any row resembling our own naming would match.
function stripQuoted(text) {
  const markers = [
    /^\s*On .{0,80}\bwrote:\s*$/im,
    /^\s*-{2,}\s*Original Message\s*-{2,}\s*$/im,
    /^\s*From:\s.+$/im,
    /^\s*_{5,}\s*$/m,
    /^\s*This is a follow-up to your previous request/im,
    /^\s*Sent from my /im,
    /iPhone\u304b\u3089\u9001\u4fe1/im
  ];

  const s = String(text == null ? '' : text);

  let cut = s.length;
  for (const m of markers) {
    const found = s.search(m);
    if (found > -1 && found < cut) cut = found;
  }

  const lines = s.slice(0, cut).split('\n');
  const kept = [];
  for (const line of lines) {
    if (/^\s*>/.test(line)) break;
    kept.push(line);
  }

  return kept.join('\n');
}

// Lowercase, reduce every non-alphanumeric run to a single space, collapse, trim.
function normalise(text) {
  return String(text == null ? '' : text)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function escapeRe(text) {
  return String(text).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const haystack = normalise(parts.map(stripQuoted).join(' '));

const rows = $input.all();

// TOKEN-SEQUENCE MATCHING. The needle must occupy whole tokens in the haystack.
//
// There used to be a second, space-insensitive pass that compared both sides with
// spaces stripped. It caused a customer-facing false positive on 2026-09-09
// (tickets 685429 and 685459): the row `mypersonality` matched the ordinary phrase
// "my personality-test results", because despacing turns that into
// "mypersonalitytestresults", which CONTAINS "mypersonality". Both customers were
// publicly told this was not our product and their tickets were solved.
//
// Since the brand is literally "Personality", any phrase of the form
// "my personality <anything>" is normal customer language, so despaced substring
// matching can never be safe here. The pass is gone and will not come back.
//
// Consequence to be aware of when adding rows: a row stored concatenated matches
// only the concatenated spelling. `mypersonality` matches "MyPersonality" (a real
// lookalike brand, one token) but NOT "my personality" (two tokens). If a
// competitor is written with spaces in the wild, add a SECOND row with the spaces
// in it - a multi-token needle still has to match as a consecutive run, so
// `personality hub` will not fire on "personality and hub".
const matches = [];
for (const r of rows) {
  const row = r.json || {};

  // active is fail-open: only an explicit negative disables a row, so a null
  // (never set) counts as active.
  const isActive = !(row.active === false || row.active === 0
    || row.active === 'false' || row.active === '0' || row.active === 'no');
  if (!isActive) continue;

  const needle = normalise(row.match_value);
  if (!needle) continue;

  // (^| ) and ( |$) anchor to token boundaries. The haystack is already reduced
  // to lowercase alphanumerics separated by single spaces, so this is exact.
  const re = new RegExp('(^| )' + escapeRe(needle) + '( |$)');

  if (re.test(haystack)) {
    matches.push({ match_value: row.match_value, normalised: needle, matched_on: 'token_sequence' });
  }
}

// Longest match first - the most specific signal is the most informative.
matches.sort((a, b) => b.normalised.length - a.normalised.length);

return [{
  json: {
    ticket_id: content.ticket_id,
    wrong_brand_matched: matches.length > 0,
    match_count: matches.length,
    matched_values: matches.map(m => m.match_value),
    matched_on: matches.map(m => m.matched_on),
    primary_match: matches.length ? matches[0].match_value : null,
    rows_checked: rows.length,
    haystack_chars: haystack.length
  }
}];

// Guard for the pending_payment branch.
//
// pending_payment means the NEXT charge attempt is outstanding. The branch that
// follows replies with macro_charged_only_for_trial_id - "you were only charged
// for the trial" - which is only true if the trial is the ONLY thing this
// customer has ever been charged for.
//
// Ticket 685518 broke that assumption: subscriptionStatus was pending_payment,
// but the transactions array held a `recurrent` charge from 2026-08-12. The
// pending payment was the NEXT renewal, not the trial. The customer had been
// charged $40 five times and was told they had only paid for the trial.
//
// Trial type list is the canonical one from `Categorise request based on
// transaction types` in the refund requests flow. Keep the two in sync.
const TRIAL_TYPES = ['trial', 'split_trial', 'no_split_trial'];

const item = $input.first();
const payload = (item && item.json) ? item.json : {};

const transactions = Array.isArray(payload.body && payload.body.transactions)
  ? payload.body.transactions
  : [];

const types = transactions.map(t => String((t && t.type) == null ? '' : t.type).trim());
const nonTrialTypes = types.filter(t => TRIAL_TYPES.indexOf(t) === -1);

// Requires POSITIVE evidence: at least one transaction, and every one of them a
// trial type. An empty array means the trial is older than the 30-day window the
// bot/search call requests, so trial-only cannot be confirmed and the ticket goes
// to the normal refund / cancellation classifier instead.
const trialOnly = transactions.length > 0 && nonTrialTypes.length === 0;

const uniqueNonTrial = [];
for (const t of nonTrialTypes) {
  if (uniqueNonTrial.indexOf(t) === -1) uniqueNonTrial.push(t);
}

const out = {};
for (const k in payload) {
  if (Object.prototype.hasOwnProperty.call(payload, k)) {
    out[k] = payload[k];
  }
}

out.trial_only_transactions = trialOnly;
out.transaction_count = transactions.length;
out.transaction_types = types;
out.non_trial_transaction_types = uniqueNonTrial;

return [{ json: out }];

// The executeWorkflow node above replaced the item with the sub-workflow's
// verdict. Response code switch downstream still expects the bot/search
// payload, so put it back and attach the verdict as a side field.
const payload = $('DEV bot/search').first().json;
const rb = $('RB: Record based checks').first().json || {};

const out = {};
for (const k in payload) {
  if (Object.prototype.hasOwnProperty.call(payload, k)) out[k] = payload[k];
}
out.record_based = rb;

return [{ json: out }];

